def migrate_status(apps, schema_editor):
    """Split old 'waiting' into waiting_print / waiting_stamp / waiting_carrier."""
    LetterInstance = apps.get_model("letters", "LetterInstance")

    # waiting + needs_printing=True → waiting_print
